//
//  driver.cc - run gls() generated by ulm.lam (from 02-normal.mlir) and check
//  it.  Everything here uses ulmBLAS, row-major (strides (cols, 1)).
//
//  1. random X (n x m), M = A A^T + n I (spd), y
//  2. b     = gls(X, M, y)                  -- ulm.lam's kernel sequence
//  3. b_inv = explicit-inverse evaluation   -- what a naive library does:
//             inv(M), two gemms, inv(S), gemvs (getrf + getri)
//  4. check: relative residual of the normal equations
//            X^T M^-1 X b = X^T M^-1 y, with M^-1 applied by an independent
//            LU solve (getrf + getrs), and ||b - b_inv|| / ||b||
//
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <random>
#include <vector>

#include <ulmblas/lapack/getrf.h>
#include <ulmblas/lapack/getri.h>
#include <ulmblas/lapack/getrs.h>
#include <ulmblas/ulmblas.h>

#include "../workspace.h"

extern "C" int64_t
gls(double *X, double *M, double *y, double *b, int8_t *work,
    int64_t *workspace_info); // generated, returns info
//  the same with M and y {ulm_lam.inout}: they may be overwritten
extern "C" int64_t
gls_inout(double *X, double *M, double *y, double *b, int8_t *work,
          int64_t *workspace_info); // generated, returns info

constexpr int N = 2000, MM = 200, REPS = 5;

static double
now()
{
    using namespace std::chrono;
    return duration<double>(steady_clock::now().time_since_epoch()).count();
}

static double
nrm2(const std::vector<double> &v)
{
    double s = 0;
    for (double x : v)
	s += x * x;
    return std::sqrt(s);
}

//  b = inv(X^T inv(M) X) X^T inv(M) y with explicit inverses
static void
glsNaive(const double *X, const double *M, const double *y, double *b)
{
    std::vector<double> Mi(M, M + N * N), T(MM * N), S(MM * MM), t(MM);
    std::vector<int> piv(N);
    ulmBLAS::getrf(N, N, Mi.data(), N, 1, piv.data(), 1);
    ulmBLAS::getri(N, Mi.data(), N, 1, piv.data(), 1); // M^-1
    ulmBLAS::gemm(MM, N, N, 1.0, false, X, 1, MM, false, Mi.data(), N, 1, 0.0,
                  T.data(), N, 1); // X^T M^-1
    ulmBLAS::gemm(MM, MM, N, 1.0, false, T.data(), N, 1, false, X, MM, 1, 0.0,
                  S.data(), MM, 1); // S
    ulmBLAS::getrf(MM, MM, S.data(), MM, 1, piv.data(), 1);
    ulmBLAS::getri(MM, S.data(), MM, 1, piv.data(), 1); // S^-1
    ulmBLAS::gemv(MM, N, 1.0, T.data(), N, 1, y, 1, 0.0, t.data(), 1);
    ulmBLAS::gemv(MM, MM, 1.0, S.data(), MM, 1, t.data(), 1, 0.0, b, 1);
}

int
main()
{
    std::mt19937_64 gen(42);
    std::uniform_real_distribution<double> rnd(-1, 1);
    std::vector<double> X(N * MM), M(N * N), A(N * N), y(N), b(MM), bInv(MM);
    for (double &x : X)
	x = rnd(gen);
    for (double &x : A)
	x = rnd(gen);
    for (double &x : y)
	x = rnd(gen);
    ulmBLAS::gemm(N, N, N, 1.0, false, A.data(), N, 1, false, A.data(), 1, N,
                  0.0, M.data(), N, 1); // A A^T
    for (int i = 0; i < N; ++i)
	M[i * N + i] += N;

    double tUlmLam = 1e30, tNaive = 1e30, t0;
    //  query the workspace once, allocate it, pass it to every call
    Workspace ws([&](int8_t *w, int64_t *i) {
	gls(X.data(), M.data(), y.data(), b.data(), w, i);
    });
    std::printf("workspace: %lld bytes\n", (long long)ws.size);
    gls(X.data(), M.data(), y.data(), b.data(), ws.work, ws.info()); // warm-up
    for (int r = 0; r < REPS; ++r) {
	t0 = now();
	gls(X.data(), M.data(), y.data(), b.data(), ws.work, ws.info());
	tUlmLam = std::min(tUlmLam, now() - t0);
    }
    glsNaive(X.data(), M.data(), y.data(), bInv.data());
    for (int r = 0; r < REPS; ++r) {
	t0 = now();
	glsNaive(X.data(), M.data(), y.data(), bInv.data());
	tNaive = std::min(tNaive, now() - t0);
    }

    //  residual r = X^T M^-1 (X b - y), M^-1 by LU (independent of potrf)
    std::vector<double> U(N * 2), LU(M), r(MM), q(MM);
    std::vector<int> piv(N);
    for (int i = 0; i < N; ++i) {
	double xb = 0;
	for (int j = 0; j < MM; ++j)
	    xb += X[i * MM + j] * b[j];
	U[i * 2 + 0] = xb - y[i];
	U[i * 2 + 1] = y[i];
    }
    ulmBLAS::getrf(N, N, LU.data(), N, 1, piv.data(), 1);
    ulmBLAS::getrs(false, false, N, 2, LU.data(), N, 1, piv.data(), 1, U.data(),
                   2, 1);
    ulmBLAS::gemv(MM, N, 1.0, X.data(), 1, MM, U.data(), 2, 0.0, r.data(), 1);
    ulmBLAS::gemv(MM, N, 1.0, X.data(), 1, MM, U.data() + 1, 2, 0.0, q.data(),
                  1);
    double res = nrm2(r) / nrm2(q);
    for (int i = 0; i < MM; ++i)
	bInv[i] -= b[i];
    double diff = nrm2(bInv) / nrm2(b);

    std::printf("n = %d, m = %d\n", N, MM);
    std::printf("ulm.lam kernels (ulmBLAS)  : %8.2f ms  (best of %d)\n",
                1e3 * tUlmLam, REPS);
    std::printf("explicit inverses       : %8.2f ms  (speedup %.1fx)\n",
                1e3 * tNaive, tNaive / tUlmLam);
    std::printf("normal-equation residual ||X^T M^-1 (Xb - y)|| / "
                "||X^T M^-1 y|| = %.2e\n",
                res);
    std::printf("||b - b_inv|| / ||b|| = %.2e\n", diff);
    //  gls_inout: M and y may be overwritten, X is read only
    std::vector<double> Mc(M), yc(y), Xc(X), b2(MM);
    Workspace ws2([&](int8_t *w, int64_t *i) {
	gls_inout(X.data(), Mc.data(), yc.data(), b2.data(), w, i);
    });
    gls_inout(X.data(), Mc.data(), yc.data(), b2.data(), ws2.work, ws2.info());
    double num = 0, den = 0;
    for (int i = 0; i < MM; ++i) {
	num += (b2[i] - b[i]) * (b2[i] - b[i]);
	den += b[i] * b[i];
    }
    double diffInout = std::sqrt(num / den);
    std::printf("gls_inout (M, y inout): workspace %lld bytes instead of "
                "%lld, ||b - b_gls|| / ||b|| = %.2e, X %s, M %s\n",
                (long long)ws2.size, (long long)ws.size, diffInout,
                X == Xc ? "unchanged" : "CHANGED",
                Mc == M ? "unchanged" : "overwritten");
    bool ok = res < 1e-10 && diff < 1e-8 && diffInout < 1e-13 && X == Xc &&
              ws2.size < ws.size;
    std::printf("%s\n", ok ? "PASS" : "FAIL");
    return ok ? 0 : 1;
}
